            ("let $r := function-lookup(QName('http://www.w3.org/2005/xpath-functions','abs'),1)([xs:untypedAtomic('-2.5')]) return ($r instance of xs:double and $r eq 2.5)", "true", false),
            ("let $r := (function($x){abs($x)})([xs:untypedAtomic('-2.5')]) return ($r instance of xs:double and $r eq 2.5)", "true", false),
            ("let $r := abs([[xs:untypedAtomic('-2.5'),()]]) return ($r instance of xs:double and $r eq 2.5)", "true", false),
            ("let $r := abs#1([[xs:untypedAtomic('-2.5'),()]]) return ($r instance of xs:double and $r eq 2.5)", "true", false),
            ("let $r := function-lookup(QName('http://www.w3.org/2005/xpath-functions','abs'),1)([[xs:untypedAtomic('-2.5'),()]]) return ($r instance of xs:double and $r eq 2.5)", "true", false),
            ("let $r := (function($x){abs($x)})([[xs:untypedAtomic('-2.5'),()]]) return ($r instance of xs:double and $r eq 2.5)", "true", false),
            ("abs('bad')", "XPTY0004", true),
            ("abs#1('bad')", "XPTY0004", true),
            ("function-lookup(QName('http://www.w3.org/2005/xpath-functions','abs'),1)('bad')", "XPTY0004", true),
            ("(function($x){abs($x)})('bad')", "XPTY0004", true),
            ("abs(xs:untypedAtomic('bad'))", "FORG0001", true),
            ("abs#1(xs:untypedAtomic('bad'))", "FORG0001", true),
            ("function-lookup(QName('http://www.w3.org/2005/xpath-functions','abs'),1)(xs:untypedAtomic('bad'))", "FORG0001", true),
            ("(function($x){abs($x)})(xs:untypedAtomic('bad'))", "FORG0001", true),
            ("abs((1,2))", "XPTY0004", true),
            ("abs#1((1,2))", "XPTY0004", true),
            ("function-lookup(QName('http://www.w3.org/2005/xpath-functions','abs'),1)((1,2))", "XPTY0004", true),
            ("(function($x){abs($x)})((1,2))", "XPTY0004", true),
            ("abs([map{}])", "FOTY0013", true),
            ("abs#1([map{}])", "FOTY0013", true),
            ("function-lookup(QName('http://www.w3.org/2005/xpath-functions','abs'),1)([map{}])", "FOTY0013", true),
            ("(function($x){abs($x)})([map{}])", "FOTY0013", true),
            ("abs([function(){1}])", "FOTY0013", true),
            ("abs#1([function(){1}])", "FOTY0013", true),
            ("function-lookup(QName('http://www.w3.org/2005/xpath-functions','abs'),1)([function(){1}])", "FOTY0013", true),
            ("(function($x){abs($x)})([function(){1}])", "FOTY0013", true),
            ("local-name-from-QName(function-name((function($f as function(item()*) as item()*){ $f })(abs#1)))", "abs", false),
        };
        foreach (var profile in new[] { XPathCompatibility.XPath31, XPathCompatibility.XPath40, XPathCompatibility.XPath40Experimental })
            foreach (var row in cases)
                yield return new object[] { profile, row.Expression, row.Expected, row.Error };
    }

    /// <summary>Checks public-call values, primitive types, signs, and required errors.</summary>
    /// <param name="profile">The XPath compatibility profile.</param>
    /// <param name="expression">The complete predicate or error expression.</param>
    /// <param name="expected">The expected value or error code.</param>
    /// <param name="error">Whether evaluation must fail.</param>
    [Theory, MemberData(nameof(Cases))]
    public void PreservesIntegerResults(XPathCompatibility profile, string expression, string expected, bool error)
    {
        string Evaluate() => XPath31Expression.Compile(expression, new CompileOptions { Compatibility = profile }).Evaluate(new EvaluationContext()).ToString();
        if (error) Assert.Contains(expected, Assert.ThrowsAny<Exception>(() => Evaluate()).Message);
        else Assert.Equal(expected, Evaluate());
    }
}
